const dialog=document.querySelector('#media-dialog');const content=document.querySelector('#media-content');let lastFocus;
const videoTitles=['Лянга в руках участников','Слово Варису','Лянга в движении','Игра на открытой площадке','Играйте в лянгу'];
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-video],[data-photo]');if(!trigger)return;lastFocus=trigger;content.replaceChildren();let media;if(trigger.dataset.video!==undefined){const i=trigger.dataset.video;media=document.createElement('video');media.src=`assets/video-${i}.mp4`;media.controls=true;media.playsInline=true;media.autoplay=true;document.querySelector('#media-title').textContent=videoTitles[Number(i)];}else{media=document.createElement('img');media.src=trigger.dataset.photo;media.alt=trigger.dataset.caption;document.querySelector('#media-title').textContent=trigger.dataset.caption;}content.append(media);dialog.showModal();document.body.style.overflow='hidden';});
function closeMedia(){dialog.close();}document.querySelector('.close').addEventListener('click',closeMedia);dialog.addEventListener('click',e=>{if(e.target===dialog)closeMedia()});dialog.addEventListener('close',()=>{content.querySelector('video')?.pause();content.replaceChildren();document.body.style.overflow='';lastFocus?.focus()});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button))});document.querySelectorAll('[data-kind]').forEach(item=>{item.hidden=filter!=='all'&&item.dataset.kind!==filter})}));
